#include <iomanip>
#include <iostream>

struct Fee {  // a struct with operator(), still an aggregate
    double bps = 0.0;
    double operator()(double notional) const {
        return notional * bps / 10000.0;
    }
};

class Order {  // private until public:
    double price_;
    int lots_;

public:
    Order(double price, int lots) : price_(price), lots_(lots) {}
    int lots() const {
        return lots_;
    }
    double notional() const {
        return price_ * lots_;
    }
};

int main() {
    std::cout << std::fixed << std::setprecision(2);
    double feed_lots = 400.5;
    int dropped = feed_lots;          // = truncates silently
    Order loose(101.25, feed_lots);   // () truncates silently too
    // Order strict{101.25, 400.5};   // error: narrowing conversion
    Order strict{101.25, 401};        // braces call the constructor
    Fee fee{1.5};                     // aggregate: bps = 1.5
    std::cout << dropped << ' ' << loose.lots() << ' ' << strict.lots() << '\n';
    std::cout << loose.notional() << ' ' << strict.notional() << ' ' << fee(strict.notional()) << '\n';
    return 0;
}

