        std::cout << "subscribed on session " << session_ << '\n';
    }
    inline static int subscribed = 0;

private:
    int session_;
};

int main() {
    Feed quotes(Session());  // declares a function: no Feed, no output
    std::cout << "feeds: " << Feed::subscribed << '\n';

    Feed trades{Session{}};  // fix 1: braces
    Feed depth((Session()));  // fix 2: extra parentheses
    Session second;
